e order number or supplier':'Type GRN number or supplier' }}" x-model="query" @focus="open=true" @input="selectedId=''; open=true" @keydown.escape="open=false" @keydown.enter.prevent="if(filtered().length) choose(filtered()[0])" class="mt-1 block w-full rounded-lg border border-line p-2"><span class="sr-only">Search {{ $kind==='receipt'?'approved orders':'goods receipts' }} by number or supplier</span></label><div x-cloak x-show="open" class="absolute z-20 mt-1 max-h-60 w-full overflow-y-auto rounded-lg border border-line bg-white shadow-lg"><template x-for="option in filtered()" :key="option.id"><button type="button" @click="choose(option)" x-text="option.label" class="block w-full px-3 py-2 text-left text-sm hover:bg-slate-100"></button></template><p x-show="filtered().length===0" class="px-3 py-2 text-sm text-slate-500">No matching {{ $kind==='receipt'?'purchase orders':'goods receipts' }}</p></div></div>@else<label class="min-w-0 flex-1 text-sm">Original posted goods receipt<select name="receipt" class="mt-1 block w-full rounded-lg border border-line p-2"><option value="">Choose a GRN</option>@foreach($receipts as $source)<option value="{{ $source->document_id }}" @selected($selectedReceipt?->document_id===$source->document_id)>{{ $source->document->number }} / {{ $source->supplier->party->legal_name }}</option>@endforeach</select></label><button class="rounded-lg bg-brand px-4 py-2 text-sm text-white">Load details</button>@endif</div>
